def charge(provider: str, amount_cents: int, customer: Customer) -> str:
    if provider == "stripe":
        intent = stripe.PaymentIntent.create(
            amount=amount_cents, currency="usd", customer=customer.stripe_id, confirm=True
        )
        return intent.id
    elif provider == "paypal":
        order = paypal_client.orders.create(amount=amount_cents / 100, payer_id=customer.paypal_id)
        return order["id"]
    elif provider == "mpesa":
        resp = mpesa.stk_push(phone=customer.phone, amount=amount_cents // 100)
        return resp.checkout_request_id
    else:
        raise ValueError(f"unknown provider: {provider}")
